<map version="1.0.1"><node TEXT="AIGC课程菜单v2｜46门·74小时"><node TEXT="通用基础" COLOR="#225cc5"><node TEXT="F01 AIGC视频入门：一条片子的生产地图（1h）" COLOR="#225cc5"><node TEXT="建立从需求到交付的全流程认知，知道每一步应该产出什么。" /><node TEXT="成果：一张个人视频生产流程图" /><node TEXT="前置：—" /></node><node TEXT="F02 把需求讲清楚：从客户想法到创作任务书（1h）" COLOR="#225cc5"><node TEXT="把“做得高级一点”等模糊要求转成可执行的创作约束。" /><node TEXT="成果：一页创作任务书与验收要点" /><node TEXT="前置：—" /></node><node TEXT="F03 选题与开头：让观众愿意继续看（1h）" COLOR="#225cc5"><node TEXT="围绕用户问题、情绪和利益点，设计可测试的选题与前三秒开头。" /><node TEXT="成果：3个选题、3版开头与选择理由" /><node TEXT="前置：—" /></node><node TEXT="F04 脚本小课：把一个卖点写成30秒故事（1h）" COLOR="#225cc5"><node TEXT="掌握可拍、可生成、可剪辑的短视频脚本写法。" /><node TEXT="成果：一份30秒脚本及压缩版" /><node TEXT="前置：—" /></node><node TEXT="F05 分镜小课：把文字变成镜头清单（1h）" COLOR="#225cc5"><node TEXT="把脚本拆成可独立生成的短镜头，控制景别和连续性。" /><node TEXT="成果：一份4—6镜分镜表" /><node TEXT="前置：—" /></node><node TEXT="F06 提示词小课：从碰运气到可控修改（1h）" COLOR="#225cc5"><node TEXT="用结构化描述明确主体、动作、环境、镜头和限制条件。" /><node TEXT="成果：一组提示词与修改对照记录" /><node TEXT="前置：—" /></node><node TEXT="F07 角色与产品一致性：建立可复用资产包（1h）" COLOR="#225cc5"><node TEXT="建立角色、产品、场景与风格参照，减少跨镜头漂移。" /><node TEXT="成果：角色／产品卡及3张一致性候选图" /><node TEXT="前置：—" /></node><node TEXT="F08 关键帧设计：先定画面，再生成运动（1h）" COLOR="#225cc5"><node TEXT="学习用起始画面、结束目标和动作衔接控制视频镜头。" /><node TEXT="成果：一组首尾画面与动作说明" /><node TEXT="前置：—" /></node><node TEXT="F09 视频生成诊断：镜头为什么失败（1h）" COLOR="#225cc5"><node TEXT="识别动作畸变、穿帮和运动失控，选择成本较低的修复方案。" /><node TEXT="成果：一个镜头的修复前后对照" /><node TEXT="前置：—" /></node><node TEXT="F10 配音与声音：让画面有节奏和情绪（1h）" COLOR="#225cc5"><node TEXT="为短片设计旁白、音乐与音效，保持听感清楚。" /><node TEXT="成果：一段20—30秒声音设计练习" /><node TEXT="前置：—" /></node><node TEXT="F11 剪辑与包装：把镜头组装成片（1h）" COLOR="#225cc5"><node TEXT="用已有素材完成粗剪、字幕、封面与适配导出。" /><node TEXT="成果：一条15—30秒练习成片" /><node TEXT="前置：—" /></node><node TEXT="F12 成片审核：质量、授权与AI标识（1h）" COLOR="#225cc5"><node TEXT="建立交付前的检查习惯，区分课堂样片与可公开发布作品。" /><node TEXT="成果：作品自查表与素材来源表" /><node TEXT="前置：—" /></node></node><node TEXT="工具入门" COLOR="#7040b4"><node TEXT="T01 画布工具上手：做出第一条产品短片（2h）" COLOR="#7040b4"><node TEXT="通过一个低复杂度产品案例，串联策划、图片、视频与成片。" /><node TEXT="成果：一条10—15秒、2—3镜产品练习片" /><node TEXT="前置：—" /></node><node TEXT="T02 转绘工具上手：拆解并重做一段视频（2h）" COLOR="#7040b4"><node TEXT="用自摄或授权素材学习视频反推、风格改写和转绘输出。" /><node TEXT="成果：一段5—10秒转绘样片及拆解表" /><node TEXT="前置：—" /></node><node TEXT="T03 导演台上手：从短剧本到剧情样片（2h）" COLOR="#7040b4"><node TEXT="围绕单场景短剧本体验剧本、分镜、资产和成片的完整流程。" /><node TEXT="成果：一条20—30秒、单场景剧情练习片" /><node TEXT="前置：—" /></node></node><node TEXT="案例实战" COLOR="#086a56"><node TEXT="P01 TVC广告：做一条15秒品牌概念片（2h）" COLOR="#086a56"><node TEXT="将一个品牌主张转成有视觉记忆点的商业广告样片。" /><node TEXT="成果：一条15秒TVC概念样片与创意说明" /><node TEXT="前置：T01" /></node><node TEXT="P02 电商产品视频：让商品卖点可视化（2h）" COLOR="#086a56"><node TEXT="从商品图片出发制作展示、使用场景和卖点字幕。" /><node TEXT="成果：一条15—20秒产品展示样片" /><node TEXT="前置：T01" /></node><node TEXT="P03 本地商家宣传：一条片讲清到店理由（2h）" COLOR="#086a56"><node TEXT="为咖啡店、民宿等真实场景设计可交付的轻宣传片。" /><node TEXT="成果：一条20—30秒商家宣传样片" /><node TEXT="前置：T01" /></node><node TEXT="P04 产品与服务讲解：把复杂流程讲明白（2h）" COLOR="#086a56"><node TEXT="把操作说明或服务流程转成易懂的视频讲解。" /><node TEXT="成果：一条30—45秒流程讲解样片" /><node TEXT="前置：T01" /></node><node TEXT="P05 数字人口播：做一条可信的讲解视频（2h）" COLOR="#086a56"><node TEXT="以授权形象和声音制作讲解型口播，处理口型、停顿和辅助画面。" /><node TEXT="成果：一条30—45秒数字人口播样片" /><node TEXT="前置：T01" /></node><node TEXT="P06 教育微课：把一个知识点讲懂（2h）" COLOR="#086a56"><node TEXT="面向开放大学和社会培训制作“一个问题、一种方法、一道练习”的教学短视频。" /><node TEXT="成果：一条45—60秒教学样片及1道自测题" /><node TEXT="前置：T01" /></node><node TEXT="P07 不出镜知识视频：用原创解释做内容（2h）" COLOR="#086a56"><node TEXT="用原创讲解和证据支撑的画面制作不出镜知识内容。" /><node TEXT="成果：一条30—45秒知识视频样片" /><node TEXT="前置：T01" /></node><node TEXT="P08 高传播创意短视频：反差、悬念与循环（2h）" COLOR="#086a56"><node TEXT="练习常见“爆款”叙事结构，把传播想法转成可测试的创意样片。" /><node TEXT="成果：一条10—20秒创意样片＋两版开头方案" /><node TEXT="前置：T01" /></node><node TEXT="P09 风格转绘：让同一段素材呈现新表达（2h）" COLOR="#086a56"><node TEXT="以自摄动作片段练习风格转换，关注人物、运动和时序稳定。" /><node TEXT="成果：一段转绘样片＋原片对照与风格说明" /><node TEXT="前置：T02" /></node><node TEXT="P10 视频出海本地化：从换语言到换表达（2h）" COLOR="#086a56"><node TEXT="把自有或授权样片改成适合一个目标市场的内容版本。" /><node TEXT="成果：一条15—30秒本地化样片＋双语脚本与改写表" /><node TEXT="前置：T02" /></node><node TEXT="P11 AI短剧：完成一个有反转的剧情场景（2h）" COLOR="#086a56"><node TEXT="围绕两人以内、一个场景的冲突完成短剧情制作。" /><node TEXT="成果：一条30—45秒短剧场景样片" /><node TEXT="前置：T03" /></node><node TEXT="P12 AI漫剧：把原创故事做成动态片段（2h）" COLOR="#086a56"><node TEXT="把原创或已获授权的短故事转成角色稳定、节奏清楚的动态漫片段。" /><node TEXT="成果：一条20—30秒漫剧样片＋后续两集梗概" /><node TEXT="前置：T03" /></node><node TEXT="P13 文旅与文化短片：让地方故事被看见（2h）" COLOR="#086a56"><node TEXT="围绕一项地方文化或一个景点制作叙事型宣传样片。" /><node TEXT="成果：一条20—30秒文旅文化样片" /><node TEXT="前置：T01/T03" /></node><node TEXT="P14 实拍＋AI特效：做一个可用的创意镜头（2h）" COLOR="#086a56"><node TEXT="在自摄镜头中加入生成元素，练习构图、遮挡与声音衔接。" /><node TEXT="成果：一段5—8秒特效镜头＋前后对照" /><node TEXT="前置：T01" /></node><node TEXT="P15 音乐视觉短片：把节奏变成画面（2h）" COLOR="#086a56"><node TEXT="为自有或授权音乐设计画面节奏与视觉主题。" /><node TEXT="成果：一条10—15秒音乐视觉片段" /><node TEXT="前置：T01" /></node><node TEXT="P16 口播转绘：把真人讲解变成风格化主持（2h）" COLOR="#086a56"><node TEXT="从自摄口播保留说话节奏，重建授权角色与视觉风格，重点检查嘴部和表情。" /><node TEXT="成果：一条10—15秒口播转绘样片＋口型检查表" /><node TEXT="前置：T02" /></node><node TEXT="P17 短剧转绘：把一场实拍戏改成新风格（2h）" COLOR="#086a56"><node TEXT="用原创或授权的双人短场景保留冲突与表演节奏，逐镜头转绘再拼接。" /><node TEXT="成果：一条15—25秒剧情转绘样片＋镜头对应表" /><node TEXT="前置：T02" /></node><node TEXT="P18 真人转动漫：把表演迁移给原创角色（2h）" COLOR="#086a56"><node TEXT="用一段真人表演驱动原创动画形象，聚焦动作、视线和表情的对应。" /><node TEXT="成果：一段5—10秒动漫表演片段＋动作对照" /><node TEXT="前置：T02" /></node><node TEXT="P19 商品广告转绘：换场景，保留商品识别（2h）" COLOR="#086a56"><node TEXT="改写商品视频的环境和氛围，学习在生成变化中保护产品轮廓、颜色和文字。" /><node TEXT="成果：一条8—15秒广告变体＋商品一致性清单" /><node TEXT="前置：T02" /></node><node TEXT="P20 文旅非遗转绘：让真实记录有视觉叙事（2h）" COLOR="#086a56"><node TEXT="在自有文化或景观素材上增加风格表达，区分艺术想象与真实记录。" /><node TEXT="成果：一条10—20秒文化转绘短片＋事实核对表" /><node TEXT="前置：T02" /></node><node TEXT="P21 教学演示转绘：突出一个动作或步骤（2h）" COLOR="#086a56"><node TEXT="对自摄操作演示进行视觉简化和风格化，突出学习对象并保留关键动作。" /><node TEXT="成果：一段10—20秒教学演示＋1道自测题" /><node TEXT="前置：T02" /></node><node TEXT="P22 多镜头转绘：解决角色与场景不连贯（2h）" COLOR="#086a56"><node TEXT="用连续三个镜头建立统一角色、服装和环境，专练跨镜头匹配。" /><node TEXT="成果：三镜连贯转绘片段＋连续性检查表" /><node TEXT="前置：T02" /></node><node TEXT="P23 转绘修复：处理闪烁、变形与口型偏差（2h）" COLOR="#086a56"><node TEXT="针对转绘常见失败诊断原因，在重生成、缩短片段和剪辑替换之间作取舍。" /><node TEXT="成果：一段5—10秒修复对照＋返修记录" /><node TEXT="前置：T02" /></node><node TEXT="P24 短剧转绘出海：做好一个多语对白场景（2h）" COLOR="#086a56"><node TEXT="以自有或授权的剧情转绘片段为起点，完成角色台词、配音与字幕的本地化。" /><node TEXT="成果：一条15—25秒多语剧情样片＋双语台词表" /><node TEXT="前置：T02" /></node><node TEXT="P25 舞蹈与音乐转绘：保留动作，设计节奏（2h）" COLOR="#086a56"><node TEXT="用简单自摄动作与授权音乐制作风格化表演，检查肢体、遮挡和节拍。" /><node TEXT="成果：一条5—10秒风格化表演＋动作检查表" /><node TEXT="前置：T02" /></node></node><node TEXT="职业交付" COLOR="#935418"><node TEXT="B01 接单与报价：把创作拆成可计价工作（1h）" COLOR="#935418"><node TEXT="为视频服务限定范围，估算工时、生成成本和修改成本。" /><node TEXT="成果：一份模拟报价单与服务范围说明" /><node TEXT="前置：—" /></node><node TEXT="B02 修改与交付：让客户意见变成任务（1h）" COLOR="#935418"><node TEXT="处理意见冲突、版本管理和项目归档，提高交付可追踪性。" /><node TEXT="成果：一份交付包目录＋修改确认单" /><node TEXT="前置：—" /></node><node TEXT="B03 作品集与获客：让客户看懂你能做什么（1h）" COLOR="#935418"><node TEXT="针对一个细分客户群设计案例展示与服务介绍。" /><node TEXT="成果：一页作品集结构＋一项服务介绍" /><node TEXT="前置：—" /></node><node TEXT="B04 发布与复盘：用数据决定下一版怎么改（1h）" COLOR="#935418"><node TEXT="用清楚的实验问题分析开头、完播和行动反馈。" /><node TEXT="成果：一份基于教学数据的A/B复盘表" /><node TEXT="前置：—" /></node><node TEXT="B05 系列化生产：把一条样片变成一组内容（1h）" COLOR="#935418"><node TEXT="沉淀脚本、资产与审核模板，为周期性内容服务建立生产节奏。" /><node TEXT="成果：一份5期内容计划及生产模板" /><node TEXT="前置：—" /></node><node TEXT="B06 作品诊断与路演：完成一次模拟验收（1h）" COLOR="#935418"><node TEXT="以已有样片为对象说明创意、制作过程、成本和改进路径。" /><node TEXT="成果：一份作品诊断表与改进计划" /><node TEXT="前置：—" /></node></node></node></map>